def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            # Find this color's 8-connected component.
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        p = (x + dx, y + dy)
                        if (dx or dy) and 0 <= p[0] < h and 0 <= p[1] < w:
                            if grid[p[0]][p[1]] == color and p not in seen:
                                seen.add(p)
                                stack.append(p)

            if len(comp) < 2:
                continue

            # Extend from the lowest point, continuing its incoming direction.
            tip = max(comp, key=lambda p: (p[0], p[1]))
            neighbors = [p for p in comp if p != tip and
                         max(abs(p[0] - tip[0]), abs(p[1] - tip[1])) == 1]
            if not neighbors:
                continue
            prev = min(neighbors, key=lambda p: (p[0], p[1]))
            dr, dc = tip[0] - prev[0], tip[1] - prev[1]
            rr, cc = tip[0] + dr, tip[1] + dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += dr
                cc += dc

    return out
